#include <iostream>

int main()
{
    int x{};
    int count{};
    int lowest{};
    int highest{};

    while (std::cin >> x)
    {
        if (count == 0)
        {
            lowest = x;
            highest = x;
        }
        else
        {
            if (x < lowest) lowest = x;
            if (x > highest) highest = x;
        }
        ++count;
    }

    std::cout << "count " << count << "\n";

    if (count == 0)
    {
        std::cout << "min none\n";
        std::cout << "max none\n";
    }
    else
    {
        std::cout << "min " << lowest << "\n";
        std::cout << "max " << highest << "\n";
    }

    return 0;
}
